def update_company_meta():
    root_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    meta_path = os.path.join(root_dir, "scripts", "data", "company_meta.json")
    
    with open(meta_path, "r", encoding="utf-8") as f:
        meta = json.load(f)
    
    print(f"Loaded {len(meta)} companies from {meta_path}.")
    
    missing_in_profiles = set(meta.keys()) - set(PROFILES.keys())
    if missing_in_profiles:
        print(f"WARNING: Tickers missing in PROFILES dictionary: {missing_in_profiles}")
    else:
        print(f"SUCCESS: All {len(PROFILES)} defined tickers have curated business profiles.")
        
    for sym, profile_text in PROFILES.items():
        if sym in meta:
            meta[sym]["business_profile"] = profile_text
        else:
            print(f"Warning: {sym} not found in company_meta.json")
            
    with open(meta_path, "w", encoding="utf-8") as f:
        json.dump(meta, f, indent=2)
        
    print(f"Updated {len(PROFILES)} company business profiles in {meta_path}.")

if __name__ == "__main__":
    update_company_meta()
